#include <bits/stdc++.h>
using namespace std;

using ll = long long;
int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin >> n;
        
        int m = 3*n;
        
        vector<ll> a(m);
        
        for(ll &x : a) cin >> x;
        
        sort(a.rbegin(), a.rend());
        
        vector<ll> prefix(m +1, 0);
        
        for(int i=0; i<m; i++) prefix[i+1] = prefix[i] + a[i];
        
        ll answer = 0;
        
        for(int x = 0; x<=n; x++){
            int maxB = n - x;
            
            auto calculate = [&](int b) -> ll{
                int scored = 3*n-2 * x - b;
                
                return 2 * prefix[x] + prefix[x+2 * b] + 3 * prefix[scored];
            };
            int bestB;
            
            if(maxB == 0){
                bestB = 0;
            }else{
                int low = 0;
                int high = maxB - 1;
                
                int fd = maxB;
                
                while(low <= high){
                    int b = (low + high)/2;
                    int scored = 3 * n -2*x-b;
                    ll delta = a[x+2*b] + a[x+2*b+1] - 3*a[scored-1];
                    
                    if(delta < 0){
                        fd = b;
                        high  = b - 1;
                    }else{
                        low = b + 1;
                    }
                }
                bestB = fd;
            }
            ll yxz = calculate(bestB);
            
            answer = max(answer, yxz);
        }
        cout << answer << "\n";
    }
    return 0;
}
